/* =====================================================
 * TFT LOW-LEVEL SPI
 * ===================================================== */

static void TFT_SPIWrite(
    const uint8_t *data,
    uint16_t length
)
{
    if (
        HAL_SPI_Transmit(
            &hspi1,
            (uint8_t *)data,
            length,
            100U
        ) != HAL_OK
    )
    {
        tft_spi_errors++;
    }
}

static void TFT_Select(void)
{
    HAL_GPIO_WritePin(
        GPIOA,
        GPIO_PIN_4,
        GPIO_PIN_SET
    );

    HAL_GPIO_WritePin(
        GPIOD,
        GPIO_PIN_3,
        GPIO_PIN_RESET
    );
}

static void TFT_Deselect(void)
{
    HAL_GPIO_WritePin(
        GPIOD,
        GPIO_PIN_3,
        GPIO_PIN_SET
    );
}

static void TFT_SetDC(uint8_t dataMode)
{
    HAL_GPIO_WritePin(
        GPIOB,
        GPIO_PIN_15,
        dataMode ? GPIO_PIN_SET : GPIO_PIN_RESET
    );
}

static void TFT_Cmd(
    uint8_t cmd,
    const uint8_t *data,
    uint8_t count
)
{
    TFT_Select();

    TFT_SetDC(0U);
    TFT_SPIWrite(&cmd, 1U);

    if (count > 0U && data != NULL)
    {
        TFT_SetDC(1U);
        TFT_SPIWrite(data, count);
    }

    TFT_Deselect();
}

static void TFT_Cmd1(
    uint8_t cmd,
    uint8_t value
)
{
    TFT_Cmd(cmd, &value, 1U);
}

static void TFT_BeginWindow(
    uint16_t x0,
    uint16_t y0,
    uint16_t x1,
    uint16_t y1
)
{
    uint8_t params[4];
    uint8_t cmd;

    TFT_Select();

    cmd = 0x2AU;
    TFT_SetDC(0U);
    TFT_SPIWrite(&cmd, 1U);

    params[0] = (uint8_t)(x0 >> 8);
    params[1] = (uint8_t)x0;
    params[2] = (uint8_t)(x1 >> 8);
    params[3] = (uint8_t)x1;

    TFT_SetDC(1U);
    TFT_SPIWrite(params, 4U);

    cmd = 0x2BU;
    TFT_SetDC(0U);
    TFT_SPIWrite(&cmd, 1U);

    params[0] = (uint8_t)(y0 >> 8);
    params[1] = (uint8_t)y0;
    params[2] = (uint8_t)(y1 >> 8);
    params[3] = (uint8_t)y1;

    TFT_SetDC(1U);
    TFT_SPIWrite(params, 4U);

    cmd = 0x2CU;
    TFT_SetDC(0U);
    TFT_SPIWrite(&cmd, 1U);

    TFT_SetDC(1U);
}

static void TFT_FillRect(
    uint16_t x,
    uint16_t y,
    uint16_t w,
    uint16_t h,
    uint16_t rgb565
)
{
    uint8_t buffer[512];
    uint32_t pixels;

    uint8_t hi = (uint8_t)(rgb565 >> 8);
    uint8_t lo = (uint8_t)rgb565;

    if (
        x >= TFT_WIDTH ||
        y >= TFT_HEIGHT ||
        w == 0U ||
        h == 0U
    )
    {
        return;
    }

    if (w > TFT_WIDTH - x)
    {
        w = TFT_WIDTH - x;
    }

    if (h > TFT_HEIGHT - y)
    {
        h = TFT_HEIGHT - y;
    }

    for (
        uint16_t i = 0U;
        i < sizeof(buffer);
        i += 2U
    )
    {
        buffer[i] = hi;
        buffer[i + 1U] = lo;
    }

    TFT_BeginWindow(
        x,
        y,
        (uint16_t)(x + w - 1U),
        (uint16_t)(y + h - 1U)
    );

    pixels = (uint32_t)w * (uint32_t)h;

    while (pixels > 0U)
    {
        uint16_t chunk =
            pixels > 256U ? 256U : (uint16_t)pixels;

        TFT_SPIWrite(
            buffer,
            (uint16_t)(chunk * 2U)
        );

        pixels -= chunk;
    }


    TFT_Deselect();
}

static void TFT_DrawRLEImage(
    uint16_t x,
    uint16_t y,
    uint16_t w,
    uint16_t h,
    const uint16_t *rle_data,
    uint32_t rle_word_count
)
{
    /* 960 bytes, one scanline of the 480-pixel RGB565 display.
     * Static allocation keeps the Cortex-M0+ stack small.
     */
    static uint8_t row_pixels[TFT_WIDTH * 2U];
    uint32_t run_index = 0U;
    uint32_t run_left = 0U;
    uint16_t run_color = 0U;

    if (rle_data == NULL || rle_word_count < 2U ||
        w == 0U || h == 0U ||
        (uint32_t)x + w > TFT_WIDTH ||
        (uint32_t)y + h > TFT_HEIGHT)
    {
        return;
    }

    /* Important: one address window, one CS assertion.
     * Never clear the full screen first: the logo covers it completely.
     */
    TFT_BeginWindow(
        x,
        y,
        (uint16_t)(x + w - 1U),
        (uint16_t)(y + h - 1U)
    );

    for (uint16_t row = 0U; row < h; row++)
    {
        for (uint16_t col = 0U; col < w; col++)
        {
            if (run_left == 0U)
            {
                if (run_index + 1U >= rle_word_count)
                {
                    /* Image is unexpectedly truncated. */
                    tft_spi_errors++;
                    TFT_Deselect();
                    return;
                }

                run_color = rle_data[run_index++];
                run_left = rle_data[run_index++];
            }

            row_pixels[(uint32_t)col * 2U] =
                (uint8_t)(run_color >> 8);
            row_pixels[(uint32_t)col * 2U + 1U] =
                (uint8_t)run_color;
            run_left--;
        }

        /* One 960-byte SPI write per row instead of thousands
         * of short, individual RLE-run transfers.
         */
        TFT_SPIWrite(row_pixels, (uint16_t)(w * 2U));
    }

    TFT_Deselect();
}

